def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome greater than the given number.
    """
    s = str(num + 1)  # start checking from the next number
    while True:
        if s == s[::-1]:
            return int(s)
        s = str(int(s) + 1)

def find_solution(a, b, n):
    """
    Find integers x and y such that ax + by = n, if possible.
    If no solution exists, return None.
    Uses Extended Euclidean Algorithm.
    """
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        gcd, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (gcd, x, y)

    gcd, x, y = extended_gcd(a, b)
    if n % gcd != 0:
        return None  # No solution

    # Scale the solution by n // gcd
    x *= n // gcd
    y *= n // gcd
    return (x, y)

def next_power_of_2(n: int) -> int:
    if n <= 1:
        return 1
    power = 1
    while power < n:
        power <<= 1
    return power

