def even_Power_Sum(n):
    # Sum of fifth power of first n even natural numbers
    # even natural numbers: 2, 4, 6, ..., 2n
    return sum((2 * i) ** 5 for i in range(1, n + 1))

def even_binomial_Coeff_Sum(n):
